CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(80) NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(16) NOT NULL DEFAULT 'user',status VARCHAR(16) NOT NULL DEFAULT 'active',plan_id VARCHAR(60) NOT NULL DEFAULT 'free',plan_expires DATETIME NULL,credits INT NOT NULL DEFAULT 30,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,scope VARCHAR(16) NOT NULL DEFAULT 'user',expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS entities (id VARCHAR(64) NOT NULL,type VARCHAR(24) NOT NULL,data LONGTEXT NOT NULL,sort_order INT DEFAULT 0,PRIMARY KEY(type,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (id INT PRIMARY KEY,data LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS records (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,kind VARCHAR(24) NOT NULL,title VARCHAR(240) NOT NULL,content MEDIUMTEXT,meta LONGTEXT,status VARCHAR(24) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS conversations (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,agent_id VARCHAR(64),title VARCHAR(240),messages LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS runs (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,goal TEXT NOT NULL,agent_ids TEXT NOT NULL,status VARCHAR(24) DEFAULT 'queued',steps LONGTEXT NOT NULL,result MEDIUMTEXT,error TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id VARCHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,product_type VARCHAR(20) NOT NULL,product_id VARCHAR(64) NOT NULL,title VARCHAR(120) NOT NULL,amount INT NOT NULL,status VARCHAR(24) DEFAULT 'pending',payment_method VARCHAR(24) NOT NULL,provider_ref VARCHAR(255),snapshot LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_requests (user_id CHAR(36) NOT NULL,request_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,order_id VARCHAR(64),checkout LONGTEXT,payment_url TEXT,instructions TEXT,ready TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,request_key),UNIQUE KEY(order_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS installs (user_id CHAR(36) NOT NULL,plugin_id VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,plugin_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS usage_logs (id CHAR(36) PRIMARY KEY,user_id CHAR(36),model_id VARCHAR(64),kind VARCHAR(24),tokens INT DEFAULT NULL,latency INT DEFAULT 0,status VARCHAR(20),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit (id CHAR(36) PRIMARY KEY,user_id CHAR(36),action VARCHAR(100),detail LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (id VARCHAR(190) PRIMARY KEY,hits INT DEFAULT 0,window_start BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media_assets (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,kind VARCHAR(16) NOT NULL,original_name VARCHAR(190) NOT NULL,mime VARCHAR(80) NOT NULL,filename VARCHAR(80) NOT NULL,bytes BIGINT NOT NULL,duration DECIMAL(9,3) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media_operations (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,kind VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id),INDEX(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
